import type { Column, Typed } from '../Column'

export type BooleanColumnType<Type extends boolean = boolean, Default extends Type = Type> = Column<Type, Default>

/**
 * A Column for a boolean type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 */
export function BooleanColumn<
    const Type extends boolean,
    const Default extends Type,
    const C extends Column<Type, Default>,
>(config: C & BooleanColumnType<Type, Default>) {
    return config as Typed<Type, C>
}
